def _lags_group_x_values(
    details: list,
    neighbors: list,
    lags: list,
    labels: dict,
    minutes: int,
    alpha: float,
) -> tuple[int, list[int], Decimal, list, dict]:
    """Validate the shared lags/group inputs and compute same-label x values.

